/**
 * Doc Shield — L1 scanner test suite.
 *
 * Runs the shipping scanner sources (copied verbatim into .build/ by prepare.mjs)
 * against hand-built malicious and benign fixtures, and asserts on the finding
 * ids each case must produce. Fixtures are generated by make_fixtures.py, which
 * writes hostile metadata directly rather than going through a zip library —
 * a zip bomb is defined by what it *declares*, not by what it contains.
 */

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

import { ThreatScanner } from './.build/services/ThreatScanner.ts';
import { HashBlacklist } from './.build/services/scanners/HashBlacklist.ts';
import { sha256Hex } from './.build/services/scanners/Sha256.ts';
import { analyzePe } from './.build/services/scanners/PEAnalyzer.ts';
import { containsAlias, precheck } from './.build/services/scanners/RequirementKeywords.ts';
import {
  checkFormats,
  extractNamingRule,
  parseRequirement
} from './.build/services/scanners/RequirementKeywords.ts';
import { checkNaming, parseNamingTemplate } from './.build/services/scanners/NamingTemplate.ts';
import {
  auditRequirement,
  describeLocalRequirements,
  scoreForFindings
} from './.build/services/RequirementAudit.ts';

const here = path.dirname(fileURLToPath(import.meta.url));
const FIXTURES = path.join(here, 'fixtures');

let passed = 0;
let failed = 0;
const failures = [];

function load(name) {
  return new Uint8Array(fs.readFileSync(path.join(FIXTURES, name)));
}

function check(label, condition, detail) {
  if (condition) {
    passed++;
  } else {
    failed++;
    failures.push(`${label}${detail ? ` — ${detail}` : ''}`);
  }
}

function ids(report) {
  return report.findings.map((finding) => finding.id);
}

function levelOf(report, id) {
  const finding = report.findings.find((item) => item.id === id);
  return finding ? finding.level : undefined;
}

/**
 * @param {string} fixture
 * @param {object} spec
 * @param {string[]} [spec.mustHave]
 * @param {string[]} [spec.mustNotHave]
 * @param {string}   [spec.verdict]
 * @param {number}   [spec.scoreBelow]
 * @param {number}   [spec.scoreAbove]
 * @param {string}   [spec.expectLevel]  `id=level` pair for a mandatory level
 */
function scenario(fixture, spec) {
  const name = fixture;
  const data = load(fixture);
  const report = ThreatScanner.scanFile(fixture, data, { blacklist: BLACKLIST });

  const present = ids(report);

  for (const id of spec.mustHave ?? []) {
    check(
      `${name} 必须命中 ${id}`,
      present.includes(id),
      `实际命中: ${present.join(', ') || '(无)'}`
    );
  }
  for (const id of spec.mustNotHave ?? []) {
    check(
      `${name} 不应命中 ${id}`,
      !present.includes(id),
      `实际命中: ${present.join(', ')}`
    );
  }
  if (spec.verdict) {
    check(
      `${name} 判定应为 ${spec.verdict}`,
      report.verdict === spec.verdict,
      `实际 ${report.verdict}（score ${report.score}）`
    );
  }
  if (spec.scoreBelow !== undefined) {
    check(
      `${name} 分数应低于 ${spec.scoreBelow}`,
      report.score < spec.scoreBelow,
      `实际 ${report.score}`
    );
  }
  if (spec.scoreAbove !== undefined) {
    check(
      `${name} 分数应不低于 ${spec.scoreAbove}`,
      report.score >= spec.scoreAbove,
      `实际 ${report.score}`
    );
  }
  if (spec.expectLevel) {
    const [id, level] = spec.expectLevel.split('=');
    check(
      `${name} 中 ${id} 应为 ${level}`,
      levelOf(report, id) === level,
      `实际 ${levelOf(report, id) ?? '(未命中)'}`
    );
  }
  return report;
}

// ---------------------------------------------------------------- blacklist

const seeded = HashBlacklist.createWithSeed();
const BLACKLIST = new HashBlacklist();
for (const entry of seeded.all()) {
  BLACKLIST.add(entry);
}

/**
 * EICAR anti-malware test vector.
 *
 * Held in memory rather than read from disk: Windows Defender blocks reads of a
 * file containing this string (verified — even `cp` returns "Permission
 * denied"), so keeping it on the filesystem would make the suite unrunnable on
 * the very host it needs to run on.
 */
const EICAR = new Uint8Array(Buffer.from(
  'X5O!P%@AP[4\\PZX54(P^)7CC)7}$EICAR-STANDARD-ANTIVIRUS-TEST-FILE!$H+H*',
  'latin1'
));

console.log('='.repeat(72));
console.log('Doc Shield L1 — 扫描器验证');
console.log('='.repeat(72));

// ------------------------------------------------------- 0. digest self-check
const eicarBytes = EICAR;
const eicarNode = crypto.createHash('sha256').update(Buffer.from(eicarBytes)).digest('hex');
const eicarMine = sha256Hex(eicarBytes);
check(
  'SHA-256 实现与 OpenSSL 一致（EICAR 样本）',
  eicarMine === eicarNode,
  `自研 ${eicarMine} / OpenSSL ${eicarNode}`
);

// A few more digests to cover the padding boundaries (55 / 56 / 119 / 120 bytes).
for (const size of [0, 1, 55, 56, 63, 64, 119, 120, 1000]) {
  const blob = new Uint8Array(size);
  for (let i = 0; i < size; i++) {
    blob[i] = (i * 37 + 11) & 0xFF;
  }
  const mine = sha256Hex(blob);
  const reference = crypto.createHash('sha256').update(Buffer.from(blob)).digest('hex');
  check(`SHA-256 边界长度 ${size} 字节`, mine === reference, `${mine} vs ${reference}`);
}

const seedHash = HashBlacklist.seedEntries()[0].sha256;
check(
  '内置黑名单种子哈希与 EICAR 文件一致',
  seedHash === eicarNode,
  `种子 ${seedHash} / 实际 ${eicarNode}`
);

