// Structural assertions on the PE parser, independent of the report layer.
const dropperAnalysis = analyzePe(load('dropper.exe'));
check('PE 解析成功', dropperAnalysis.valid, dropperAnalysis.error);
check('PE 机器类型为 x86', dropperAnalysis.machine === 0x14C, `0x${dropperAnalysis.machine.toString(16)}`);
check(
  'PE 导入函数数量为 6',
  dropperAnalysis.importedFunctionCount === 6,
  `实际 ${dropperAnalysis.importedFunctionCount}: ${dropperAnalysis.imports
    .map((entry) => `${entry.dll}[${entry.functions.join('|')}]`)
    .join(' ')}`
);
check(
  'PE 导入表被正确解析出 DLL',
  dropperAnalysis.imports.map((entry) => entry.dll).includes('urlmon.dll'),
  dropperAnalysis.imports.map((entry) => entry.dll).join(', ')
);
check(
  'PE 节表被正确解析',
  dropperAnalysis.sections.length === 1 && dropperAnalysis.sections[0].name === '.rdata',
  JSON.stringify(dropperAnalysis.sections)
);
check(
  'PE 入口点位于节内',
  dropperAnalysis.entryPointInsideSection === true
);

const packedAnalysis = analyzePe(load('packed.exe'));
check(
  '加壳样本的代码节熵高于 7.2',
  packedAnalysis.sections[0].entropy > 7.2,
  `实际 ${packedAnalysis.sections[0].entropy.toFixed(3)}`
);

